Definition A_SMALLOC_2_K : Z := 0x531fc.          (* [comment removed for export] *) (* [comment removed for export] *)
Definition A_UAR_GOT_K : Z := 0x0f5ea8.           (* [comment removed for export] *) (* [comment removed for export] *)
