Section RED.
  Variable R : art_layout.
  #[local] Hint Extern 0 heap_layout => exact (arl_L R) : typeclass_instances.
  Variable HIA : artA asegs R.
  Local Notation AL := (arl_AL R).
  Local Notation L := (arl_L R).
  Hypothesis IMG : asan_img_ok AL.
  Hypothesis UARG : arl_uar_got R = A_UAR_GOT_K.
  Hypothesis SM2 : arl_smalloc R 2 = A_SMALLOC_2_K.
  Hypothesis NS1 : 0 <= arl_need_smalloc R.
  Hypothesis NEEDR : 0 <= arl_need_rt R.
  Hypothesis GROW : mpi_grow_stmtA_sz asegs R HIA A_MPI_GROW.
  Hypothesis AMS : arl_amemset R = A_ASAN_MEMSET_EC.
  Hypothesis AMC : arl_amemcpy R = A_ASAN_MEMCPY_K.
  Hypothesis CMUL : mpi_core_mul_stmtA asegs R HIA A_MPI_CORE_MUL.
  Hypothesis RTC : forall m, arl_rtc R m -> asan_rtc m.
  (* [comment removed for export] *)
  Hypothesis PRIMG : forall a, rtc_prist a -> hl_img_lo L <= a < hl_img_hi L.
  Hypothesis DIMG : hl_img_lo L <= hl_data_lo L /\ hl_data_hi L <= hl_img_hi L.
  Hypothesis ROIMG : forall a, ro_addr asegs (wa a) = true -> 0 <= a < 2^64 -> hl_img_lo L <= a < hl_img_hi L.

  Section Call.
  Variables (h : HST asegs R HIA) (LB LF : list blk) (m : mem) (mo : Model).
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (dX : mpd) (lo d : Z).
  Local Notation X := (md_addr dX).
  Definition KFRAME : list cell := [C8 s2; C8 s1; C8 s0; C8 ra].
  Hypothesis JC : JCA asegs R HIA h LB LF m dX sp lo 32 KFRAME.
  Hypothesis TPV : tp = Z_to_bv 64 (arl_tp R).
  Hypothesis RAE : bv_unsigned ra mod 2 = 0.
  Hypothesis UWX : uw_obj R X 16 d.
  Hypothesis D0 : 0 <= d.
  Hypothesis BUD : havol asegs R HIA h + grow_PHI 16 <= AVOL_MAX.
  Hypothesis BUDF : hfr asegs R HIA h + red_FRn d <= FR_MAX.
  Hypothesis C24H : cnt24 LB + C24_ECP_RED <= C24MAX.
  Hypothesis SLO2 : lo <= bv_unsigned sp - 544 - arl_need_ecp R.
  Hypothesis LFB : (length LF + 1 <= 512)%nat.
  (* [comment removed for export] *)
  Definition KPOST : config -> Prop :=
    mpi_binop_postA asegs R HIA ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc h LB LF dX (reducer_R 16 dX LB)
      (grow_PHI 16) (red_FRn d) lo m mo.
  Local Ltac jc_open := pose proof JC as [NEEDR' HND DIMG' ROIMG' HH MX NST XW XLS LOS FS16 SLO TOP SPA FSZ].
  Local Ltac basic_factsA hc :=
    pose proof (hcs_ok asegs R HIA hc) as CSOK; pose proof (cs_ok_sb _ _ CSOK) as SB64;
    pose proof (art_alwf asegs R HIA) as ALWF'; unfold al_wf in ALWF'; pose proof IMG as IMG'; unfold asan_img_ok in IMG';
    pose proof (art_lo asegs R HIA) as ALO; pose proof (alloc_ceiling_pos (L := arl_L R)) as ACP;
    pose proof (hcs_stack asegs R HIA hc) as SCS0;
    pose proof (arl_need_rt_amem R) as NRA; pose proof (arl_need_rt_malloc R) as NRM; pose proof (arl_need_rt_free R) as NRF;
    pose proof (arl_need_ecp_rt R) as NER;
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; cbn [Z.pow Z.of_N Pos.pow] in SPR.
  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Lemma r_ret : forall (v f : Z) (hc : HST asegs R HIA) (LBc : list blk) (mc : mem) (dXc : mpd) (r : Z)
      (xra xt0 xt1 xt2 xs0 xs1 xa1 xa2 xa3 xa4 xa5 xa6 xa7 xs2 xt3 xt4 xt5 xt6 : word),
    XJA asegs R HIA h LB LF m dX sp lo 32 KFRAME [] v f hc LBc mc dXc ->
    reducer_R 16 dX LB r dXc -> v <= grow_PHI 16 -> f <= red_FRn d ->
    aevtA asegs (KF asegs R HIA hc mo) KPOST
      (MS (mkR xra (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp xt0 xt1 xt2 xs0 xs1 (Z_to_bv 64 r) xa1 xa2 xa3 xa4 xa5 xa6 xa7
               xs2 s3 s4 s5 s6 s7 s8 s9 s10 s11 xt3 xt4 xt5 xt6) F (Z_to_bv 64 0xd6938) fc None mc (seg_rom asegs)).
  Proof.
    jc_open. intros until xt6. intros J HR HV HF. basic_factsA hc.
    pose proof J as [MI1 ST1 FR1 HH1 HT1 HS1 HF1 HCS1 HV1 HFR1 MX1 AD1 PD1 NSc OUT1 FRS1 FRA1 HPX1 OX1 XP1 XLS1 NM1]. cbn [app] in HH1.
    pose proof (hm_top asegs R HIA hc LBc LF mc HH1) as HTOP.
    assert (LO0 : 0 <= lo) by (clear - LOS ALO ACP; lia).
    assert (SCS : crange (hcs asegs R HIA hc) lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| clear - LOS; lia| rewrite HS1; pose proof (hm_top asegs R HIA h LB LF m HH); clear - H TOP; lia]).
    pose proof (AIh_laws asegs R HIA hc) as LAWS. pose proof (KF_kinv asegs R HIA hc mo) as KINV.
    unfold KFRAME in FR1. replace (bv_unsigned sp - 32) with (bv_unsigned sp + -32) in FR1, ST1 by (clear; lia).
    pose proof (munch_refl ([] : list ivl) mc) as MU. pose proof (wmono_refl asegs mc) as WM.
    do 4 zstep.
    zstep.
    replace (bv_unsigned sp + -32 + 32) with (bv_unsigned sp) by (clear; lia). rewrite ?(Z_to_bv_bv_unsigned sp).
    zstep.
    apply aevtA_done. intros mo9 [HK9 MF9]. unfold KPOST.
    eapply (xa_post asegs R HIA h LB LF m dX sp lo 32 KFRAME JC); [exact J| exact HR| exact HK9| exact MF9| exact HV| exact HF].
  Qed.
  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Lemma r_kob : forall (v f : Z) (hc : HST asegs R HIA) (LBc : list blk) (mc : mem) (dXc : mpd)
      (xra xt0 xt1 xt2 xa1 xa2 xa3 xa4 xa5 xa6 xa7 xs2 xt3 xt4 xt5 xt6 : word),
    XJA asegs R HIA h LB LF m dX sp lo 32 KFRAME [] v f hc LBc mc dXc ->
    md_own dXc = LHeap -> 16 <= md_n dXc ->
    (forall ws r, -2^31 < r <= 0 -> r <> MBEDTLS_ERR_MPI_ALLOC_FAILED -> reducer_R 16 dX LB r (relimb dXc ws)) ->
    v <= grow_PHI 16 -> f <= red_FRn d ->
    aevtA asegs (KF asegs R HIA hc mo) KPOST
      (MS (mkR xra (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp xt0 xt1 xt2 (Z_to_bv 64 X) (Z_to_bv 64 (al_sb (arl_AL R))) (Z_to_bv 64 0)
               xa1 xa2 xa3 xa4 xa5 xa6 xa7 xs2 s3 s4 s5 s6 s7 s8 s9 s10 s11 xt3 xt4 xt5 xt6) F (Z_to_bv 64 0xd6900) fc None mc (seg_rom asegs)).
  Proof.
    intros until xt6; intros J0 EO HNK HR0 BV BF.
    jc_open; pose proof (jca_facts asegs R HIA h LB LF m dX sp lo 32 KFRAME JC) as (LO0 & LOSP & SP64 & ALO' & ACP' & X0 & X16 & XAL & DSX & LEN & NR).
    basic_factsA hc.
    pose proof (xa_facts _ _ _ _ _ _ _ _ _ _ _ _ JC _ _ _ _ _ _ _ J0) as (ND1 & LEN1 & NR1 & SG1 & CX1 & OWN0 & OWN1).
    pose proof J0 as [MI1 ST1 FR1 HH1 HT1 HS1 HF1 HCS1 HV1 HFR1 MX1 AD1 PD1 NSc OUT1 FRS1 FRA1 HPX1 OX1 XP1 XLS1 NM1]. cbn [app] in HH1.
    ddestruct (OWN1 ltac:(rewrite EO; discriminate)) as (_ & N1 & XIN & XPAL & XARR & P0 & PC & PI & OP & P47).
    pose proof (hm_top asegs R HIA hc LBc LF mc HH1) as HTOP.
    assert (SCS : crange (hcs asegs R HIA hc) lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| clear - LOS; lia| rewrite HS1; pose proof (hm_top asegs R HIA h LB LF m HH); clear - H TOP; lia]).
    pose proof (AIh_laws asegs R HIA hc) as LAWS; pose proof (KF_kinv asegs R HIA hc mo) as KINV.
    unfold mpi_cells in CX1.
    pose proof (conj J0 I) as J0box. clear J0 HV1 HFR1 FRS1 FRA1 HPX1 OUT1 NM1 MX1 XP1 XLS1 NSc HCS1 HF1 OWN0 OWN1.
  (* [comment removed for export] *)
    pose proof (hm_abase asegs R HIA hc LBc LF mc HH1) as ABm. pose (lxi := lxA_img (arl_AL R) IMG).
    lx_pre. lx_run_tac (PLAN [0xd7184] [] 80%N).
    lx_tree.
    lazymatch goal with E : ?mx = mc |- _ => subst mx end.
    destruct J0box as [J0 _].
    assert (KS : koblitz_stmtB asegs R HIA A_ECP_KOBLITZ).
    { apply A_ecp_koblitz_spec; first [ exact IMG | exact NS1 | exact NEEDR | exact CMUL | exact (A_mpi_core_add_spec (arl_AL R) IMG)
          | rewrite UARG; reflexivity | rewrite SM2; reflexivity | rewrite AMS; reflexivity | rewrite AMC; reflexivity ]. }
    assert (PR : forall a, A_RP_P256K1 <= a < A_RP_P256K1 + 8 -> rtc_prist a).
    { intros a Ha. unfold rtc_prist, rtc_pristine. do 2 apply Exists_cons_tl. apply Exists_cons_hd. cbn [fst snd]. unfold A_RP_P256K1 in Ha. clear - Ha. lia. }
    pose proof (PRIMG _ (PR A_RP_P256K1 ltac:(clear; lia))) as RK1. pose proof (PRIMG _ (PR (A_RP_P256K1 + 7) ltac:(clear; lia))) as RK2.
    assert (RTAB : koblitz_rtabB asegs R HIA A_RP_P256K1 [Z_to_bv 64 0x3d1; Z_to_bv 64 0x1]).
    { unfold koblitz_rtabB. split; [reflexivity|]. split; [unfold A_RP_P256K1; clear; lia|]. split; [unfold A_RP_P256K1; reflexivity|].
      split; [clear - RK1; lia|]. split; [clear - RK2; lia|].
      intros hq LBq LFq mq HHq. split.
      - pose proof (asan_rtc_const mq A_RP_P256K1 (u32s [Z_to_bv 64 0x3d1; Z_to_bv 64 0x1]) (RTC mq (hm_rtc asegs R HIA hq _ _ mq HHq)) ltac:(vm_compute; reflexivity) ltac:(vm_compute; reflexivity)) as RO.
        destruct RO as [_ Hb]. cbn [cells_bytes cbytes] in Hb. rewrite app_nil_r in Hb. exact Hb.
      - eapply (AImgGlobals.aobj_img asegs (arl_AL R)); [apply (A_mpi_copy.hcs_img_cs_cp R HIA IMG)| eapply (hm_img_shadow asegs R HIA); exact HHq| vm_compute; reflexivity]. }
    assert (RPLO : A_RP_P256K1 + 8 <= lo).
    { pose proof (alloc_ceiling_lo (L := arl_L R)) as ACL. unfold A_RP_P256K1. clear - ACL ALO LOS. lia. }
    unfold koblitz_stmtB in KS.
    eapply (aevtA_cut_evtA_KF asegs R HIA hc mo).
    { eapply KS with (h := hc) (LB := LBc) (LF := LF) (X := md_p dXc) (XB := 4 * md_n dXc) (RP := A_RP_P256K1) (bits := 256) (lo := lo)
                     (xs := md_limbs dXc) (rs := [Z_to_bv 64 0x3d1; Z_to_bv 64 0x1]);
        rewrite ?(unsigned_lit (bv_unsigned sp + -32)) by (clear - SPR SLO2 LOS ALO ACP NER NEEDR; lia).
      all: try first [ exact HH1 | exact LFB | exact XARR | exact XIN | exact RTAB | exact RPLO | exact LOS | exact TPV | exact MI1 | exact ST1 ].
      all: try (left; reflexivity); try (right; left; reflexivity); try (right; right; reflexivity).
      all: try (unfold koblitz_xl; rewrite LEN1; change (256 / 16) with 16; clear - HNK; lia).
      all: try (rewrite LEN1; clear; lia).
      all: try (clear - XPAL; Z.div_mod_to_equations; lia).
      all: try (unfold KOBLITZ_STACK; clear - SLO2; lia).
      all: try (rewrite HT1; clear - TOP; lia).
      all: try (clear - SPA; Z.div_mod_to_equations; lia).
      all: try (unfold A_RP_P256K1; reflexivity).
      all: try reflexivity.
      all: try (vm_compute; reflexivity).
      all: match goal with |- ?g => idtac "KOB-PRE-LEFT:" g end. }
    intros ms' PO. unfold koblitz_postB in PO.
    destruct PO as (k0 & k1 & k2 & ka0 & ka1 & ka2 & ka3 & ka4 & ka5 & ka6 & ka7 & k3 & k4 & k5 & k6 & m' & h' & xs'
                    & E & ARR' & LEN' & HCS' & HT' & HS' & HF' & HV' & HFR' & HKI & HH' & PW & MI' & ST').
    subst ms'.
    lazymatch goal with |- aevtA _ _ _ (MS _ _ (ret_pc (Z_to_bv 64 ?x)) _ _ _ _) =>
      replace (ret_pc (Z_to_bv 64 x)) with (Z_to_bv 64 x) by (symmetry; apply ret_pc_even; [ lia | reflexivity ]) end.
    rewrite ?(unsigned_lit (bv_unsigned sp + -32)) in PW, ST' by (clear - SPR SLO2 LOS ALO ACP NER NEEDR; lia).
    pose proof (xa_kob asegs R HIA h LB LF m dX sp lo 32 KFRAME JC [] v f hc LBc mc dXc (koblitz_xl 256) m' h' xs' J0 EO
                  ltac:(unfold koblitz_xl; change (256 / 16) with 16; clear - HNK; lia) MI' ST' PW HCS' HT' HS' HF' HV' HFR' HH' ARR' LEN') as J2.
    intros mo1 [HK1 MF1]. apply (aevtA_enter asegs (KF asegs R HIA h' mo) _ _ mo1 (conj (proj2 (HKI mo1) HK1) MF1)).
    clear LAWS KINV. pose proof (AIh_laws asegs R HIA h') as LAWS. pose proof (KF_kinv asegs R HIA h' mo) as KINV.
    pose proof (munch_refl ([] : list ivl) m') as MU. pose proof (wmono_refl asegs m') as WM.
    zstep.
    eapply r_ret with (r := 0); [exact J2| apply HR0; [clear; lia| unfold MBEDTLS_ERR_MPI_ALLOC_FAILED; clear; lia]| exact BV| exact BF].
  Qed.
  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Lemma r_main : forall (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
    HK asegs R HIA h mo -> stk asegs m lo (bv_unsigned sp) -> mem_inv asegs m ->
    mpd_aobjA asegs (arl_AL R) (hcs asegs R HIA h) m dX ->
    aevtS asegs KPOST (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 X) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                                      t3 t4 t5 t6) F (Z_to_bv 64 A_ECP_MOD_P256K1) fc None m (seg_rom asegs)) mo).
  Proof.
    intros until t6; intros HK ST MI OXA. unfold A_ECP_MOD_P256K1.
    jc_open; pose proof (jca_facts asegs R HIA h LB LF m dX sp lo 32 KFRAME JC) as (LO0 & LOSP & SP64 & ALO' & ACP' & X0 & X16 & XAL & DSX & LEN & NR).
    basic_factsA h.
    pose proof (hm_top asegs R HIA h LB LF m HH) as HTOP.
    assert (SCS : crange (hcs asegs R HIA h) lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| clear - LOS; lia| clear - TOP HTOP; lia]).
    destruct OXA as [OX _].
    pose proof (AIh_laws asegs R HIA h) as LAWS. pose proof (KF_kinv asegs R HIA h mo) as KINV.
    apply (aevtA_enter asegs (KF asegs R HIA h mo) _ _ mo (conj HK (mo_frame_refl mo))).
    pose proof (munch_refl [(lo, bv_unsigned sp)] m) as MU. pose proof (wmono_refl asegs m) as WM.
    carve_frame 32%nat ST.
    do 5 zstep.
    lazymatch goal with |- aevtA _ _ _ (MS _ _ _ _ _ ?mx _) => rename mx into m1 end.
    replace (bv_unsigned sp + -32) with (bv_unsigned sp - 32) in FR, ST by (clear; lia).
    first [ change (rw_cells asegs m1 (bv_unsigned sp - 32) KFRAME) in FR
          | let t := type of FR in idtac "PRO-FR:" t; fail 1 ].
    pose proof (xa_start _ _ _ _ _ _ _ _ _ _ _ _ JC m1 HH MI ST FR OX MU WM) as J0.
    pose proof (hm_abase asegs R HIA h LB LF m1 HH) as AB.
    pose proof (abase_got _ _ _ AB) as GOT. pose proof (abase_gsb _ _ _ AB) as GSB. rewrite (proj1 IMG') in GOT.
    clear MU WM. pose proof (munch_refl ([] : list ivl) m1) as MU; pose proof (wmono_refl asegs m1) as WM.
    zstep. zstep. zstep. clear GOT GSB AB.
    do 2 zstep.
    zstep.
    pose proof (xa_X _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ J0) as MX1.
    destruct XW as [CW DXP].
    clear MU WM.
    eapply aevtA_call.
    { intros mo1 [HK1 MF1]. pose proof GROW as CP. unfold mpi_grow_stmtA_sz in CP.
      eapply CP with (h := h) (LB := LB) (LF := LF) (dX := dX) (v := 16) (lo := lo) (d := d);
        rewrite ?(unsigned_lit (bv_unsigned sp + -32)) by qlia; try eassumption; try reflexivity.
      all: try (split; [eapply client_wrange_sp_mono; [| exact CW]; clear; lia| exact DXP]).
      all: try (split; [exact OX| intros EST; exfalso; exact (NST EST)]).
      all: try (eapply uw_obj_uwc; [exact UWX| rewrite unsigned_lit by (clear - X0 X16; lia); clear; lia]).
      all: try (intros ON; destruct (XLS ON) as [XL|XL]; [left; exact XL| right; clear - XL; lia]).
      all: unfold grow_PHI, grow_FR, red_FRn, calls_FR, fr_charge, C24_GROW, C24_ECP_RED in *; unfold AVOL_CALL in *;
           try (clear - LOS SLO SLO2 NEEDR NER NRM NRF NRA SPA SPR BUD BUDF C24H D0 LOSP TOP; lia).
      all: match goal with |- ?g => idtac "GROW-PRE-LEFT:" g end. }
    intros ms' mo' (mo1 & [HK1 MF1] & PO). unfold mpi_binop_postA in PO.
    destruct PO as (y0 & y1 & y2 & ya1 & ya2 & ya3 & ya4 & ya5 & ya6 & ya7 & y3 & y4 & y5 & y6 & m2 & mo2 & h2 & LB2 & dX2 & r
                    & E & MI2 & ST2 & MF2 & HP2 & HT2 & HS2 & HF2 & HK2 & HCS2 & HV2 & HFR2 & HH2 & MX2 & OUT2 & FRA2 & GR).
    injection E as E1 E2. subst ms' mo'.
    rewrite ?(unsigned_lit (bv_unsigned sp + -32)) in ST2, HP2 by qlia. cbn [md_addr] in HP2.
    lazymatch goal with |- aevtS _ _ (mkCfg (MS _ _ (ret_pc (Z_to_bv 64 ?x)) _ _ _ _) _) =>
      replace (ret_pc (Z_to_bv 64 x)) with (Z_to_bv 64 x) by (symmetry; apply ret_pc_even; [ lia | reflexivity ]) end.
    presA_transport HP2.
    replace (bv_unsigned sp + -32) with (bv_unsigned sp - 32) in ST2 by (clear; lia).
    pose proof (grow_R_keep _ _ _ _ _ _ GR OUT2) as BK.
    pose proof (xa_binop _ _ _ _ _ _ _ _ _ _ _ _ JC _ _ _ _ _ _ _ (bv_unsigned sp + -32) (grow_PHI 16) (grow_FR d) J0 ltac:(clear - SLO2 NER NEEDR; lia)
                  ltac:(unfold grow_PHI; unfold AVOL_CALL; clear; lia) ltac:(unfold grow_FR, calls_FR, fr_charge; clear - D0; lia)
                  MI2 ST2 HP2 HT2 HS2 HF2 HCS2 HV2 HFR2 HH2 MX2 OUT2 BK FRA2) as J1.
    apply (aevtA_enter asegs (KF asegs R HIA h2 mo) _ _ mo2 (conj HK2 (mo_frame_trans _ _ _ MF1 MF2))).
    clear LAWS KINV. pose proof (AIh_laws asegs R HIA h2) as LAWS. pose proof (KF_kinv asegs R HIA h2 mo) as KINV.
    pose proof (munch_refl ([] : list ivl) m2) as MU; pose proof (wmono_refl asegs m2) as WM.
    zstep. if_cases KR; zify_cond KR.
    - destruct GR as [[(R0 & _)|(RF & EQ)] FRg]; [exfalso; apply KR; rewrite R0; reflexivity|]. subst r dX2.
      eapply r_ret; [exact J1| apply reducer_R_fail| unfold grow_PHI; unfold AVOL_CALL; clear; lia| unfold grow_FR, red_FRn, calls_FR, fr_charge; clear - D0; lia].
    - destruct GR as [[(R0 & GSG & GN & GPD & GLM & GID)|(RF & EQ)] FRg]; [| exfalso; subst r; clear - KR; unfold MBEDTLS_ERR_MPI_ALLOC_FAILED in KR; vm_compute in KR; lia].
      subst r.
      destruct (grow_ok_facts asegs m2 LB2 LB dX dX2 16 MX2 OUT2 ltac:(split; [left; repeat split; assumption| exact FRg]) ltac:(clear; lia)) as (GO & GNN & _).
      eapply r_kob; [exact J1| exact GO| rewrite GNN; clear; lia| | unfold grow_PHI; unfold AVOL_CALL; clear; lia| unfold grow_FR, red_FRn, calls_FR, fr_charge; clear - D0; lia].
      intros ws r Hr Hne.
      exact (reducer_R_ok 16 dX dX2 LB LB2 ws r asegs m2 MX2 OUT2 ltac:(split; [left; repeat split; assumption| exact FRg]) ltac:(clear; lia) (conj Hr Hne)).
    all: match goal with |- ?g => idtac "MAIN-LEFT:" g end.
  Qed.
